// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract ReentryAttacker {
    Reentrancy_bonus public target;
    uint256 public maxReenters;
    uint256 public reenterCount;

    constructor(Reentrancy_bonus _t) {
        target = _t;
    }

    function attack(uint256 _max) external {
        maxReenters = _max;
        reenterCount = 0;
        target.getFirstWithdrawalBonus(address(this));
    }

    receive() external payable {
        if (reenterCount < maxReenters) {
            reenterCount++;
            try target.getFirstWithdrawalBonus(address(this)) {} catch {}
        }
    }
}

contract InvMutTest is Test {
    Reentrancy_bonus c;

    function setUp() public {
        c = new Reentrancy_bonus();
    }

    function _runAttack(uint256 depth, uint256 funding) internal {
        ReentryAttacker atk = new ReentryAttacker(c);
        vm.deal(address(c), funding);
        atk.attack(depth);
        assertLe(address(atk).balance, 100);
    }

    function testFuzz_noOverpayViaReentrancy(uint8 depth, uint96 funding) public {
        uint256 d = bound(uint256(depth), 1, 5);
        uint256 f = bound(uint256(funding), 1 ether, 10 ether);
        _runAttack(d, f);
    }
}
